       box-shadow: 0 16px 28px rgba(37, 99, 235, 0.28);
     }

     button:focus-visible,
     input:focus-visible {
       outline: 3px solid rgba(37, 99, 235, 0.25);
       outline-offset: 2px;
     }

     .status {
       min-height: 1.25rem;
       font-size: 0.92rem;
       color: var(--muted);
     }

     .status.success {
       color: #166534;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Terms of Use</h1>
     <p>Please confirm your agreement before continuing.</p>

     <form id="consent-form" novalidate>
       <div class="form-field">
         <input id="consent" name="consent" type="checkbox" required>
         <div class="field-copy">
           <label for="consent">I agree to the terms of use</label>
           <span class="helper-text">You must accept the terms to submit this form.</span>
         </div>
       </div>

       <button type="submit">Submit</button>
       <div class="status" id="status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const consent = document.getElementById('consent');
     const status = document.getElementById('status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       if (!consent.checked) {
         status.textContent = 'Please agree to the terms of use to continue.';
         status.classList.remove('success');
         consent.focus();
         return;
       }

       status.textContent = 'Consent recorded.';
       status.classList.add('success');
     });
   </script>
 </body>
